public class ValidAnagram {
    public static void main(String[] args) {
        String s = "anagram", t = "nagaram";
        if (s.length() != t.length()) { System.out.println("false"); return; }
        int[] counts = new int[26];
        for (int i = 0; i < s.length(); i++) { counts[s.charAt(i) - 'a']++; counts[t.charAt(i) - 'a']--; }
        for (int c : counts) if (c != 0) { System.out.println("false"); return; }
        System.out.println("true");
    }
}

public class SearchRotated {
    public static void main(String[] args) {
        int[] nums = {4, 5, 6, 7, 0, 1, 2}; int target = 0;
        int low = 0, high = nums.length - 1;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (nums[mid] == target) { System.out.println(mid); return; }
            if (nums[low] <= nums[mid]) {
                if (target >= nums[low] && target < nums[mid]) high = mid - 1; else low = mid + 1;
            } else {
                if (target > nums[mid] && target <= nums[high]) low = mid + 1; else high = mid - 1;
            }
        }
        System.out.println(-1);
    }
}

